package com.aac.ieojwo.report.controller;
import com.aac.ieojwo.common.api.ApiResponse;import com.aac.ieojwo.report.service.ReportService;import com.aac.ieojwo.report.service.ReportService.ReportResponse;import org.springframework.http.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.oauth2.core.oidc.user.OidcUser;import org.springframework.web.bind.annotation.*;import java.time.Instant;
@RestController @RequestMapping("/api/v1/me/aac-users/{userId}/report")public class ReportController{private final ReportService service;public ReportController(ReportService s){service=s;}@GetMapping public ApiResponse<ReportResponse> report(@AuthenticationPrincipal OidcUser p,@PathVariable Long userId,@RequestParam Instant from,@RequestParam Instant to){return ApiResponse.ok(service.report(p,userId,from,to));}@GetMapping(value="/pdf",produces=MediaType.APPLICATION_PDF_VALUE)public ResponseEntity<byte[]> pdf(@AuthenticationPrincipal OidcUser p,@PathVariable Long userId,@RequestParam Instant from,@RequestParam Instant to){byte[] bytes=service.pdf(service.report(p,userId,from,to));return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=malmoa-report.pdf").body(bytes);}}
